
DROP TABLE IF EXISTS `assessments_questions`;

CREATE TABLE `assessments_questions` (
  `aq_id` int(11) NOT NULL AUTO_INCREMENT,
  `aq_parent_aq_id` int(11) DEFAULT NULL,
  `aq_aqc_id` int(11) DEFAULT NULL,
  `aq_type` int(11) DEFAULT NULL,
  `aq_title` text NOT NULL,
  `aq_text` text,
  `aq_order` int(11) DEFAULT NULL,
  `aq_active` tinyint(1) DEFAULT '1',
  `aq_create_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `aq_update_date` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`aq_id`)
) ENGINE=InnoDB AUTO_INCREMENT=286 DEFAULT CHARSET=utf8 CHECKSUM=1 DELAY_KEY_WRITE=1 ROW_FORMAT=DYNAMIC;

/*Data for the table `assessments_questions` */

insert  into `assessments_questions`(`aq_id`,`aq_parent_aq_id`,`aq_aqc_id`,`aq_type`,`aq_title`,`aq_text`,`aq_order`,`aq_active`,`aq_create_date`,`aq_update_date`) values (1,NULL,1,1,'Does the practice know the specifications by which it has to determine how it will comply with the standard ?',NULL,1,1,'2014-06-16 21:35:10','0000-00-00 00:00:00'),(2,1,1,1,'Does the practice have a clear understanding of what \"required\" specifications are as defined in the HIPAA Security Regulations ?',NULL,2,1,'2014-06-25 21:16:31','0000-00-00 00:00:00'),(3,1,1,1,'Does the practice have a clear understanding of what \"addressable\" standards are as defined in the HIPAA Security Regulations ?',NULL,3,1,'2014-06-25 21:20:57',NULL),(4,1,1,1,'Does the practice have a reference of how to determine \"required\" and \"addressable\" standards ?',NULL,4,1,'2014-06-25 21:21:04',NULL),(5,NULL,2,1,'Does the practice have a Risk Management Policy that identifies the risks of an unauthorized individual inappropriately accessing ePHI ?',NULL,5,1,'2014-06-25 22:06:24',NULL),(6,5,2,1,'Does the practice know what a Risk Management Assessment and a Risk Management Policy are ?',NULL,6,1,'2014-06-25 22:08:25',NULL),(7,5,2,1,'Has the practice conducted a thorough assessment of the risk+A1s of where the practice is vulnerable of an authorized person accessing ePHI ?',NULL,7,1,'2014-06-25 22:10:40',NULL),(8,5,2,1,'Has that risk assessment been documented ?',NULL,8,1,'2014-06-25 22:11:02',NULL),(9,5,2,1,'Does the practice have a Rick Management policy for managing on-going risk ?',NULL,9,1,'2014-06-25 22:11:25',NULL),(10,5,2,1,'Is the Risk Management Policy communicated to the workforce ?',NULL,10,1,'2014-06-25 22:11:39',NULL),(11,NULL,4,1,'Does the practice know when and how to sanction practice members if they violate security policies and procedures',NULL,11,1,'2014-06-26 10:48:42',NULL),(12,11,4,1,'Does the practice have a workforce sanction policy for workforce members who violated the practice\'s s