/*Table structure for table `assessments_questions_categories` */

DROP TABLE IF EXISTS `assessments_questions_categories`;

CREATE TABLE `assessments_questions_categories` (
  `aqc_id` int(11) NOT NULL AUTO_INCREMENT,
  `aqc_parent_id` int(11) DEFAULT NULL,
  `aqc_name` varchar(255) DEFAULT NULL,
  `aqc_citation` varchar(255) DEFAULT NULL,
  `aqc_specification` varchar(255) DEFAULT NULL,
  `aqc_description` text,
  `aqc_active` tinyint(1) DEFAULT '1',
  `aqc_create_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `aqc_update_date` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  PRIMARY KEY (`aqc_id`)
) ENGINE=InnoDB AUTO_INCREMENT=52 DEFAULT CHARSET=utf8;

/*Data for the table `assessments_questions_categories` */

insert  into `assessments_questions_categories`(`aqc_id`,`aqc_parent_id`,`aqc_name`,`aqc_citation`,`aqc_specification`,`aqc_description`,`aqc_active`,`aqc_create_date`,`aqc_update_date`) values (1,NULL,'General Rules','§164.306(d)(1) and §164.306(d)(2)','Implementation Specifications','A covered entity must comply will the standards as provided',1,'2014-06-25 20:27:57','0000-00-00 00:00:00'),(2,NULL,'Administrative Safeguards','§164.308(a)(1)(ii)(A)','Risk Analysis','Conduct an accurate and thorough assessment of the potential risks and vulnerabilities to the confidentiality, integrity and availability of ePHI held by the practice',1,'2014-06-25 20:31:47','0000-00-00 00:00:00'),(3,2,'Administrative Safeguards','§164.308(a)(1)(ii)(B)','Risk Management','Implement security measures sufficient to reduce risks and vulnerabilities to a reasonable and appropriate level',1,'2014-06-25 20:32:46','0000-00-00 00:00:00'),(4,NULL,'Administrative Safeguards','§164.308(a)(1)(ii)(C)','Sanction Policy','Apply appropriate sanctions against workforce members who fail to comply with security policies and procedures',1,'2014-06-25 20:33:08','0000-00-00 00:00:00'),(5,NULL,'Administrative Safeguards','§164.308(a)(1)(ii)(D)','Information System Activity Review','Implement procedures to regularly review records of information system activity and security incident tracking reports',1,'2014-06-25 20:36:33','0000-00-00 00:00:00'),(6,NULL,'Administrative Safeguards','§164.308(a)(2) ','Chief Security Officer','Identify the person who is responsible for the development and implementation of the policies and procedure',1,'2014-06-25 20:37:10','0000-00-00 00:00:00'),(7,NULL,'Administrative Safeguards','§164.308(a)(3)(ii)(A)','Authorization and/or Supervision','Implement procedures for the authorization and/or supervision of workforce members who work with ePHI or in locations ',1,'2014-06-25 20:37:55','0000-00-00 00:00:00'),(8,NULL,'Administrative Safeguards','§164.308(a)(3)(ii)(B)','Workforce Clearance Procedure','Implement procedures to determine that the access of a workforce member to ePHI is appropriate',1,'2014-06-25 20:38:33','0000-00-00 00:00:00'),(9,NULL,'Administrative Safeguards','§164.308(a)(3)(ii)(C) ','Termination Procedure','Implement procedures for terminating access to ePHI when the employment of a workforce member end or the workforce member\'s clearance changes',1,'2014-06-25 20:39:09','0000-00-00 00:00:00'),(10,NULL,'Administrative Safeguards','§164.308(a)(4)(ii)(A) ','Isolating Health Care Clearinghouse Functions ','If a clearinghouse is part of the health care organization\'s function, the clearinghouse must implement  policies and procedures that protect the ePHI from unauthorized access',1,'2014-06-25 20:39:44','0000-00-00 00:00:00'),(11,NULL,'Administrative Safeguards','§164.308(a)(4)(ii)(B) ','Access Authorization','Implement policies and procedures for granting access to ePHI through access to a workstation, transaction, program, process or other program',1,'2014-06-25 20:41:47','0000-00-00 00:00:00'),(12,11,'Administrative Safeguards','§164.308(a)(4)(ii)(C) ','Access Establishment and Modification','Implement policies and procedures that, based upon the entity\'s access authorization policies, establish, document, review and modify a user\'s right of access to a workstation, transaction, program or process',1,'2014-06-25 20:42:28','0000-00-00 00:00:00'),(13,NULL,'Administrative Safeguards','§164.308(a)(5)(ii)(A) ','Security Reminders','Periodic security updates',1,'2014-06-25 20:43:23','0000-00-00 00:00:00'),(14,NULL,'Administrative Safeguards','§164.308(a)(5)(ii)(B)','Protection from Malicious Software','Procedures for guarding against, detecting and reporting malicious software',1,'2014-06-25 20:43:24','0000-00-00 00:00:00'),(15,NULL,'Administrative Safeguards','§164.308(a)(5)(ii)(C)','Log-in Monitoring','Procedures for monitoring log-in attempts and reporting discrepancies',1,'2014-06-25 20:45:07','0000-00-00 00:00:00'),(16,NULL,'Administrative Safeguards','§164.308(a)(5)(ii)(D) ','Password Management ','Procedures for creating, changing and safeguarding passwords',1,'2014-06-25 20:45:47','0000-00-00 00:00:00'),(17,NULL,'Administrative Safeguards','§164.308(a)(6)(ii) ','Security Incidents - Response and Reporting ','Implement policies and procedures to identify and respond to suspected or known security incidents, mitigate to the extent practicable, harmful effects of security incidents known by the covered entity; and document security incidents',1,'2014-06-25 20:45:49','0000-00-00 00:00:00'),(18,NULL,'Administrative Safeguards','§164.308(a)(7)(ii)(A) ','Data Backup Plan','Establish and implement procedures to create and maintain retrievable exact copies of ePHI',1,'2014-06-25 20:46:30','0000-00-00 00:00:00'),(19,NULL,'Administrative Safeguards','§164.308(a)(7)(ii)(B) ','Disaster Recovery Plan ','Establish (and implement as needed) procedures to restore any lost data',1,'2014-06-25 20:48:15','0000-00-00 00:00:00'),(20,NULL,'Administrative Safeguards','§164.308(a)(7)(ii)(C) ','Emergency Mode Operation Plan','Establish (and implement as needed) procedures to enable continuation of critical business processes for protection of the security of ePHI while operating in an emergency mode',1,'2014-06-25 20:48:16','0000-00-00 00:00:00'),(21,NULL,'Administrative Safeguards','§164.308(a)(7)(ii)(D) ','Testing and Revision Procedures ','Implement procedures for the periodic testing and revision of contingency plans',1,'2014-06-25 20:48:47','0000-00-00 00:00:00'),(22,NULL,'Administrative Safeguards','§164.308(a)(7)(ii)(E)','Applications and Data Criticality Analysis','Assess the relative criticality of specific applications and data in support of other contingency plan components',1,'2014-06-25 20:49:29','0000-00-00 00:00:00'),(23,NULL,'Administrative Safeguards','§164.308(a)(8)(4) ','Written contract or other arrangement','Document the satisfactory assurances required by this regulation that the business associate meets the applicable requirements',1,'2014-06-25 20:50:02','0000-00-00 00:00:00'),(24,NULL,'Physical Safeguards','§164.310(a)(2)(i) ','Contingency Operations','Establish (and implement as needed) procedures that allow facility access in support of restoration of lost data under the disaster recovery plan and emergency mode operations plan in the event of an emergency',1,'2014-06-25 20:50:39','0000-00-00 00:00:00'),(25,NULL,'Physical Safeguards','§164.310(a)(2)(ii) ','Facility Security Plan','Implement policies and procedures to safeguard the facility and the equipment from unauthorized access, tampering and theft',1,'2014-06-25 20:51:07','0000-00-00 00:00:00'),(26,NULL,'Physical Safeguards','§164.310(a)(2)(iii) ','Access Control and Validation Procedures','Implement policies and procedures to control and validate a person\'s access to facilities based on their role or function and control access to software programs for testing and revisions',1,'2014-06-25 20:51:07','0000-00-00 00:00:00'),(27,NULL,'Physical Safeguards','§164.310(a)(2)(iv)','Maintenance Records ','Implement policies and procedures to document repairs and modifications to the physical components of the facility which are related to security',1,'2014-06-25 20:51:08','0000-00-00 00:00:00'),(28,NULL,'Physical Safeguards','§164.310(b)','Workstation Use','Implement policies and procedures that specify the proper functions to be performed, the manner in which those functions are to be performed and the physical attributes of the surroundings of a specific workstation or class of workstations that can access ePHI',1,'2014-06-25 20:51:09','0000-00-00 00:00:00'),(29,NULL,'Physical Safeguards','§164.310(c)','Workstation Security','Implement physical safeguards for all workstations, and other devices, that access ePHI to restrict access to authorized users',1,'2014-06-25 20:54:21','0000-00-00 00:00:00'),(30,NULL,'Physical Safeguards','§164.310(d)(2)(i)','Disposal','Implement policies and procedures to address the final disposition of ePHI and/or the hardware or electronic media on which it is stored',1,'2014-06-25 20:54:42','0000-00-00 00:00:00'),(31,NULL,'Physical Safeguards','§164.310(d)(2)(ii)','Media Use','Implement policies and procedures for removal of ePHI from electronic media before the media is made available for re-use',1,'2014-06-25 20:53:47','0000-00-00 00:00:00'),(32,NULL,'Physical Safeguards','§164.310(d)(2)(iii)','Accountability','Maintain a record of the movements of hardware and electronic media and any person responsible for the movement',1,'2014-06-25 20:53:47','0000-00-00 00:00:00'),(33,NULL,'Physical Safeguards','§164.310(d)(2)(iv)','Data Backup and Storage ','Create and retrievable copy of ePHI, when needed, before movement of equipment',1,'2014-06-25 20:53:49','0000-00-00 00:00:00'),(34,NULL,'Technical Safeguards','§164.312(a)(2)(i)','Unique User Identification','Assign a unique name and/or number for identifying and tracking user identity',1,'2014-06-25 20:56:21','0000-00-00 00:00:00'),(35,NULL,'Technical Safeguards','§164.312(a)(2)(ii)','mergency Access Procedure','Establish (and implement as needed) procedures for obtaining necessary ePHI during an emergency',1,'2014-06-25 20:56:22','0000-00-00 00:00:00'),(36,NULL,'Technical Safeguards','§164.312(a)(2)(iii)','Automatic Logoff','Implement electronic procedures that terminate an electronic session after a predetermined time of inactivity',1,'2014-06-25 20:56:22','0000-00-00 00:00:00'),(37,NULL,'Technical Safeguards','§164.312(a)(2)(iv)','Encryption and Decryption','Implement a mechanism to encrypt and decrypt ePHI',1,'2014-06-25 20:56:23','0000-00-00 00:00:00'),(38,NULL,'Technical Safeguards','§164.312(b) ','Audit Controls','Implement hardware, software and/or procedural mechanisms that record and examine activity in information systems that contain ePHI',1,'2014-06-25 20:56:24','0000-00-00 00:00:00'),(39,NULL,'Technical Safeguards','§164.312(c)(1) ','Integrity','Implement policies and procedures to protect ePHI from improper alteration or destruction',1,'2014-06-25 20:58:57','0000-00-00 00:00:00'),(40,NULL,'Technical Safeguards','§164.312(c)(2)','Mechanism to Authenticate ePHI','Implement electronic mechanisms to corroborate that ePHI has not been altered or destroyed in an unauthorized manner',1,'2014-06-25 20:58:58','0000-00-00 00:00:00'),(41,NULL,'Technical Safeguards','§164.312(d) ','Person or entity authentication','Implement procedures to verify that a person or entity seeking access to ePHI is the one claimed',1,'2014-06-25 20:58:59','0000-00-00 00:00:00'),(42,NULL,'Technical Safeguards','§164.312(e)(2)(i)','Integrity Controls','Implement security measures to ensure that electronically transmitted ePHI is not properly modified without detection until disposed of',1,'2014-06-25 20:58:59','0000-00-00 00:00:00'),(43,NULL,'Technical Safeguards','§164.312(e)(2)(ii) ','Encryption','Implement a mechanism to encrypt ePHI whenever being transmitted',1,'2014-06-25 20:59:01','0000-00-00 00:00:00'),(44,NULL,'Organizational Requirements','§164.314(a)(1)(ii)','Business Associate contracts','A covered entity is not in compliance if the covered entity knows of a pattern of an activity or practice of the business associate that constituted a material breach of the business associate\'s obligations unless the covered entity took reasonable steps to cure the breach ',1,'2014-06-25 21:02:37','0000-00-00 00:00:00'),(45,NULL,'Organizational Requirements','§164.314(a)(2)(i)A), (B), (C), (D) ','Business Associate contracts ','Implementation - Business Associate Agreements must provide that the Business Associate will include the following requirements',1,'2014-06-25 21:02:08','0000-00-00 00:00:00'),(46,NULL,'Policies and Procedures and Documentation Requirements','§164.316 (a) ','Policies and Procedures and Documentation Requirements','Implement reasonable and appropriate policies to comply with the standards, implementation specifications or other requirements of the regulation',1,'2014-06-25 21:02:09','0000-00-00 00:00:00'),(47,NULL,'Policies and Procedures and Documentation Requirements','§164.316 (b)(2)(i)','Time Limit','Retain the required documentation for 6 years from the date of the creation',1,'2014-06-25 21:02:10','0000-00-00 00:00:00'),(48,NULL,'Policies and Procedures and Documentation Requirements','§164.316 (b)(2)(ii) ','Availability','Make documentation available to those responsible for implementing the procedures to which the documentation pertains',1,'2014-06-25 21:02:10','0000-00-00 00:00:00'),(49,NULL,'Policies and Procedures and Documentation Requirements','§164.316 (b)(2)(iii) ','Updates','Periodically review documentation and update as needed in response to environmental or operational changes affecting security of the ePHI',1,'2014-06-25 21:02:11','0000-00-00 00:00:00'),(50,NULL,'Impact of the Use of Mobile Devices on HIPAA Compliance',NULL,NULL,NULL,1,'2014-06-25 21:02:12','0000-00-00 00:00:00'),(51,NULL,'Impact of Social Media on HIPAA Security',NULL,NULL,NULL,1,'2014-06-25 21:05:35','0000-00-00 00:00:00');

